\mathsf{ConvCert}_{HOL}
=
\{(M,N,s):\exists m\in\mathbb N\
s:m+1\to\mathsf{Tm}_{HOL}
\land s(0)=M\land s(m)=N
\land\forall i<m\ ((s(i),s(i+1))\in\to_1^{HOL}\lor(s(i+1),s(i))\in\to_1^{HOL})\}.

\operatorname{LineOK}_{HOL}(\Gamma,p,k)
\Longleftrightarrow
p:n\to\mathsf{Fm}_{HOL}
\land k<n
\land
\bigl(p(k)\in\Gamma\cup\mathsf{Ax}_{HOL}
\lor
\exists \vec A\
\bigl(\exists r\in\mathbb N\,\exists e:r\to k\ (\vec A:r\to\mathsf{Fm}_{HOL}\land\forall i<r\ \vec A(i)=p(e(i)))\land ((\vec A),p(k))\in\mathsf{Rule}_{HOL}
\land \operatorname{GenFresh}_{HOL}(\Gamma,\vec A,p(k))\bigr)\bigr),
